  ('n3', 35, 15, '追加注文', 'ついかちゅうもん', 'pesanan tambahan', 'nomina', '追加注文を承ります。', 'ついかちゅうもんを うけたまわります。', 'Saya menerima pesanan tambahan.'),
  ('n3', 35, 16, '飲み放題', 'のみほうだい', 'minum sepuasnya', 'nomina', '飲み放題の店です。', 'のみほうだいの みせです。', 'Ini toko dengan minum sepuasnya.'),
