  ('n3', 35, 18, '定食', 'ていしょく', 'set menu', 'nomina', '定食を二つください。', 'ていしょくを ふたつ ください。', 'Tolong dua set menu.'),
  ('n3', 35, 19, '単品', 'たんぴん', 'menu satuan', 'nomina', '単品でも頼めます。', 'たんぴんでも たのめます。', 'Bisa dipesan satuan juga.'),
  ('n3', 35, 20, 'お通し', 'おとおし', 'hidangan pembuka', 'nomina', 'お通しをお出しします。', 'おとおしを おだし します。', 'Saya menyajikan hidangan pembukanya.'),
  ('n3', 35, 21, '皿洗い', 'さらあらい', 'mencuci piring', 'nomina', '皿洗いを手伝います。', 'さらあらいを てつだいます。', 'Saya membantu mencuci piring.'),
  ('n3', 35, 22, '給水', 'きゅうすい', 'pengisian air', 'nomina', 'お客様に給水します。', 'おきゃくさまに きゅうすい します。', 'Saya mengisi air untuk tamu.'),
  ('n3', 35, 23, '席数', 'せきすう', 'jumlah kursi', 'nomina', '席数は四十です。', 'せきすうは よんじゅうです。', 'Jumlah kursinya empat puluh.'),
  ('n3', 35, 24, '予約席', 'よやくせき', 'kursi reservasi', 'nomina', 'ここは予約席です。', 'ここは よやくせきです。', 'Ini kursi reservasi.'),
  ('n3', 35, 25, '窓際', 'まどぎわ', 'pinggir jendela', 'nomina', '窓際の席が空いています。', 'まどぎわの せきが あいて います。', 'Kursi pinggir jendela kosong.'),
  ('n3', 35, 26, '個室', 'こしつ', 'ruang privat', 'nomina', '個室をご用意します。', 'こしつを ごようい します。', 'Kami siapkan ruang privatnya.'),
  ('n3', 35, 27, '通路側', 'つうろがわ', 'sisi lorong', 'nomina', '通路側でよろしいですか。', 'つうろがわで よろしいですか。', 'Apakah sisi lorong tidak apa-apa?'),
  ('n3', 35, 28, '席案内', 'せきあんない', 'pengantar ke kursi', 'nomina', '席案内をします。', 'せきあんないを します。', 'Saya mengantar ke kursinya.'),
  ('n3', 35, 29, '料理説明', 'りょうりせつめい', 'penjelasan hidangan', 'nomina', '料理説明をしながら出します。', 'りょうりせつめいを しながら だします。', 'Saya menyajikan sambil menjelaskan hidangannya.'),
  ('n3', 35, 30, '席順', 'せきじゅん', 'urutan tempat duduk', 'nomina', '席順を決めます。', 'せきじゅんを きめます。', 'Saya menentukan urutan tempat duduknya.')
